import { EDeviceType, EFirmwareType } from '@onekeyfe/hd-shared';

import { ETranslations } from '@onekeyhq/shared/src/locale';
import deviceUtils from '@onekeyhq/shared/src/utils/deviceUtils';
import { isProtocolV2ProductType } from '@onekeyhq/shared/src/utils/hardwareDeviceTypes';
import type {
  ICheckAllFirmwareReleaseResult,
  IFirmwareUpdateDetectStatusSnapshot,
  IFirmwareUpdatesDetectStatus,
  IPro2FirmwareUpdateTarget,
} from '@onekeyhq/shared/types/device';

import type { IDeviceType } from '@onekeyfe/hd-core';
import type { IntlShape } from 'react-intl';

export function selectFirmwareUpdateDetectStatus({
  connectId,
  persistedStatus,
  snapshot,
}: {
  connectId: string;
  persistedStatus: IFirmwareUpdatesDetectStatus | undefined;
  snapshot: IFirmwareUpdateDetectStatusSnapshot | undefined;
}) {
  const persistedDetectStatus = persistedStatus?.[connectId];
  if (snapshot && snapshot.requestedConnectId !== connectId) {
    return persistedDetectStatus;
  }
  if (snapshot?.resolved) {
    return snapshot.status;
  }
  return persistedDetectStatus;
}

export async function getFirmwareUpdateUSBPreflightParams(
  result:
    | Partial<
        Pick<
          ICheckAllFirmwareReleaseResult,
          | 'features'
          | 'deviceType'
          | 'updatingConnectId'
          | 'originalConnectId'
          | 'isBootloaderMode'
        >
      >
    | undefined,
) {
  const usbConnectId = await deviceUtils.buildDeviceUSBConnectId({
    features: result?.features,
  });
  const isBootloaderMode = result?.features
    ? await deviceUtils.isBootloaderModeByFeatures({
        features: result.features,
      })
    : result?.isBootloaderMode;
  const expectedDeviceId = [
    result?.features?.deviceId,
    result?.features?.device_id,
  ].find((id) => {
    const value = id?.trim();
    return value && !/^0+$/.test(value);
  });
  const bootloaderRecoveryDeviceType =
    isBootloaderMode &&
    !usbConnectId &&
    !expectedDeviceId &&
    result?.deviceType !== EDeviceType.Unknown
      ? result?.deviceType
      : undefined;

  let connectProtocol: 'V1' | 'V2' | undefined;
  if (isProtocolV2ProductType(result?.deviceType)) {
    connectProtocol = 'V2';
  } else if (bootloaderRecoveryDeviceType) {
    connectProtocol = 'V1';
  }

  return {
    connectId:
      usbConnectId ?? result?.updatingConnectId ?? result?.originalConnectId,
    connectProtocol,
    ...(expectedDeviceId && !usbConnectId ? { expectedDeviceId } : {}),
    ...(bootloaderRecoveryDeviceType ? { bootloaderRecoveryDeviceType } : {}),
  };
}

export function getFirmwareUpdateDeviceTitle(
  result: ICheckAllFirmwareReleaseResult,
) {
  if (result.deviceName) {
    return result.deviceName;
  }

  return result.deviceType
    ? deviceUtils.getDefaultDeviceLabel(result.deviceType)
    : undefined;
}

export function isPro2SafeOSFirmwareUpdate(
  result: ICheckAllFirmwareReleaseResult | undefined,
) {
  if (!result || !isProtocolV2ProductType(result.deviceType)) {
    return false;
  }
  return (
    result.updateInfos?.firmware?.hasUpgrade === true ||
    result.pro2TargetsToUpdate?.some(
      (target) => target === 'app_v1' || target === 'app_v2',
    ) === true
  );
}

export function hasProtocolV2FirmwareUpdateTarget(
  result: ICheckAllFirmwareReleaseResult | undefined,
  target: IPro2FirmwareUpdateTarget,
) {
  return result?.pro2TargetsToUpdate?.includes(target) === true;
}

export function getProtocolV2ResourceReleaseId(
  result: ICheckAllFirmwareReleaseResult | undefined,
) {
  if (!hasProtocolV2FirmwareUpdateTarget(result, 'resource')) {
    return undefined;
  }
  const archiveSha256 = result?.pro2ResourceArchive?.archiveSha256;
  if (!archiveSha256) {
    return undefined;
  }
  return `SHA-256 ${archiveSha256.slice(0, 12)}`;
}

export type IProtocolV2FirmwareVersionDisplayItem = {
  target: 'safeos' | IPro2FirmwareUpdateTarget;
  currentVersion: string | null;
  targetVersion: string | null;
  releaseIdentifierOnly?: boolean;
};

export function getProtocolV2FirmwareVersionTitle({
  target,
  intl,
}: {
  target: IProtocolV2FirmwareVersionDisplayItem['target'];
  intl: IntlShape;
}) {
  if (target === 'safeos') return 'SafeOS';
  if (target === 'boot') {
    return intl.formatMessage({ id: ETranslations.global_bootloader });
  }
  if (target === 'coprocessor') {
    return intl.formatMessage({ id: ETranslations.global_bluetooth });
  }
  if (target === 'resource') {
    return intl.formatMessage({ id: ETranslations.global_resources });
  }
  if (target === 'app_v1') return 'App P1';
  if (target === 'app_v2') return 'App P2';
  return target.toUpperCase();
}

export function getProtocolV2FirmwareVersionDisplayItems(
  result: ICheckAllFirmwareReleaseResult | undefined,
  { includeComponents = false }: { includeComponents?: boolean } = {},
): IProtocolV2FirmwareVersionDisplayItem[] {
  if (!result || !isProtocolV2ProductType(result.deviceType)) {
    return [];
  }

  const versionInfo = result.protocolV2FirmwareVersionInfo;
  const items: IProtocolV2FirmwareVersionDisplayItem[] = [
    {
      target: 'safeos',
      currentVersion: versionInfo?.safeOS.currentVersion ?? null,
      targetVersion: versionInfo?.safeOS.targetVersion ?? null,
    },
  ];

  if (!includeComponents) {
    return items;
  }

  for (const target of result.pro2TargetsToUpdate ?? []) {
    if (target === 'resource') {
      items.push({
        target,
        currentVersion: null,
        targetVersion: getProtocolV2ResourceReleaseId(result) ?? null,
        releaseIdentifierOnly: true,
      });
    } else {
      const component = versionInfo?.components.find(
        (item) => item.target === target,
      );
      items.push({
        target,
        currentVersion: component?.currentVersion ?? null,
        targetVersion: component?.targetVersion ?? null,
      });
    }
  }

  return items;
}

export function getTargetFirmwareTypeLabel({
  firmwareType,
  intl,
}: {
  firmwareType: EFirmwareType | undefined;
  intl: IntlShape;
}) {
  if (!firmwareType) {
    return '';
  }

  return intl.formatMessage({
    id:
      firmwareType === EFirmwareType.BitcoinOnly
        ? ETranslations.device_firmware_type_btc_only__label
        : ETranslations.device_firmware_type_multichain__label,
  });
}

/** Whether an update replaces the firmware type (universal ↔ Bitcoin-only). */
export function isFirmwareTypeSwitch(
  firmware:
    | {
        fromFirmwareType: EFirmwareType | undefined;
        toFirmwareType: EFirmwareType | undefined;
      }
    | undefined,
): boolean {
  return (
    firmware?.fromFirmwareType !== undefined &&
    firmware.toFirmwareType !== undefined &&
    firmware.fromFirmwareType !== firmware.toFirmwareType
  );
}

/** Product name, not translated. */
const BITCOIN_ONLY_VERSION_PREFIX = 'Bitcoin';

/**
 * Short word in front of a version number on the install and changelog
 * pages: Bitcoin-only builds read "Bitcoin 4.21.0"; the universal build is
 * the unmarked default and reads "4.21.0". The full type labels stay on
 * titles and banners, where there is room for them (OK-63518).
 */
export function getFirmwareVersionTypePrefix(
  firmwareType: EFirmwareType | undefined,
): string | undefined {
  return firmwareType === EFirmwareType.BitcoinOnly
    ? BITCOIN_ONLY_VERSION_PREFIX
    : undefined;
}

/**
 * Developer mode lists the Pro 2 component targets unless the Pro 2 debug
 * preference hides them. Shared by the changelog and the install page.
 */
export function shouldHidePro2FirmwareDebugInfo({
  developerModeEnabled,
  hidePro2FirmwareDebugInfo,
  deviceType,
}: {
  developerModeEnabled: boolean;
  hidePro2FirmwareDebugInfo: boolean | undefined;
  deviceType: IDeviceType | undefined;
}) {
  return (
    developerModeEnabled &&
    deviceType === EDeviceType.Pro2 &&
    hidePro2FirmwareDebugInfo === true
  );
}
